<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { post } from '../api'; const router=useRouter(),password=ref(''),confirm=ref(''),error=ref(''),saving=ref(false); async function save(){error.value='';if(password.value!==confirm.value){error.value='两次输入的密码不一致';return}saving.value=true;try{await post('/auth/change-password',{password:password.value});router.push('/')}catch(e){error.value=(e as Error).message}finally{saving.value=false}}</script>
<template><div class="login-form-area" style="min-height:100vh"><form class="login-form" @submit.prevent="save"><div class="login-accent" style="margin:0 0 30px"/><span class="eyebrow">01 / 01</span><h1 style="margin-top:10px">先设置你的新密码</h1><p class="subtitle">默认密码仅用于首次进入系统。</p><div class="field-group"><label>新密码</label><input v-model="password" type="password" minlength="12" class="input" /></div><div class="field-group"><label>确认新密码</label><input v-model="confirm" type="password" minlength="12" class="input" /></div><p class="subtitle" style="font-size:12px">密码至少 12 位，建议使用密码管理器。</p><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="saving">{{saving?'保存中…':'保存并进入系统 →'}}</button></form></div></template>
